/** Offline MotorLab1.6.3 PCM for ambient/race vehicles. Player uses its own live engine. */
const decode=(b64,referenceRpm)=>{const raw=atob(b64),data=new Float32Array(raw.length/2);for(let i=0;i<data.length;i++){let n=raw.charCodeAt(i*2)|(raw.charCodeAt(i*2+1)<<8);if(n>32767)n-=65536;data[i]=n/32768;}return {data,rate:24000,referenceRpm};};
export const NPC_ENGINES={i4:decode('',1800.4488560266664),i6t:decode('',1800.623347837473),v8:decode('',1800.7532803762638),rotary:decode('',1800.29965151071)};
